/**
 * SessionsTab — Client session history with filtering and status tracking.
 */

import { useState } from 'react';
import { format } from 'date-fns';
import { Award, Clock, Dumbbell, CalendarCheck } from 'lucide-react';
import { type FullClientProfile } from '@/lib/client-data';

type StatusFilter = 'all' | 'completed' | 'confirmed' | 'pending' | 'cancelled';

export default function SessionsTab({ client }: { client: FullClientProfile }) {
  const [filter, setFilter] = useState<StatusFilter>('all');
  const sessions = filter === 'all' ? client.sessions : client.sessions.filter((s) => s.status === filter);

  const stats = {
    total: client.sessions.length,
    completed: client.sessions.filter((s) => s.status === 'completed').length,
    rate: Math.round((client.sessions.filter((s) => s.status === 'completed').length / Math.max(1, client.sessions.length)) * 100),
    thisMonth: client.sessions.filter((s) => new Date(s.date) > new Date(Date.now() - 30 * 86400000)).length,
  };

  const statusConfig = {
    completed: { bg: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400', icon: Award },
    confirmed: { bg: 'bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400', icon: CalendarCheck },
    pending: { bg: 'bg-yellow-50 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-400', icon: Clock },
    cancelled: { bg: 'bg-red-50 text-red-700 dark:bg-red-900/20 dark:text-red-400', icon: Dumbbell },
  };

  return (
    <div className="space-y-6">
      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Sessions', value: stats.total, color: 'text-gray-900 dark:text-white' },
          { label: 'Completed', value: stats.completed, color: 'text-emerald-600' },
          { label: 'This Month', value: stats.thisMonth, color: 'text-[#00AEEF]' },
          { label: 'Completion Rate', value: `${stats.rate}%`, color: 'text-amber-600' },
        ].map((s) => (
          <div key={s.label} className="bg-white dark:bg-[#141414] rounded-xl p-4 border border-gray-100 dark:border-white/5 text-center">
            <p className="text-xs text-gray-500 dark:text-gray-400">{s.label}</p>
            <p className={`text-2xl font-bold font-mono mt-1 ${s.color}`}>{s.value}</p>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="flex gap-2 flex-wrap">
        {(['all', 'completed', 'confirmed', 'pending', 'cancelled'] as const).map((status) => (
          <button
            key={status}
            onClick={() => setFilter(status)}
            className={`px-4 py-2 rounded-full text-sm font-medium capitalize transition-colors ${
              filter === status ? 'bg-[#00AEEF] text-white' : 'bg-gray-100 dark:bg-[#1A1A1A] text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-white/5'
            }`}
          >{status === 'all' ? 'All Sessions' : status}</button>
        ))}
      </div>

      {/* Sessions Table */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl border border-gray-100 dark:border-white/5 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead><tr className="bg-gray-50 dark:bg-[#1A1A1A] text-gray-500 dark:text-gray-400 text-xs uppercase">
              <th className="text-left px-4 py-3">Date</th>
              <th className="text-left px-4 py-3">Type</th>
              <th className="text-left px-4 py-3">Duration</th>
              <th className="text-left px-4 py-3">Status</th>
              <th className="text-left px-4 py-3">Notes</th>
            </tr></thead>
            <tbody className="divide-y divide-gray-100 dark:divide-white/5">
              {sessions.map((s) => {
                const cfg = statusConfig[s.status];
                const Icon = cfg.icon;
                return (
                  <tr key={s.id} className="hover:bg-gray-50 dark:hover:bg-[#1A1A1A] transition-colors">
                    <td className="px-4 py-3 text-gray-700 dark:text-gray-300">{format(new Date(s.date), 'MMM d, yyyy')}</td>
                    <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{s.type}</td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">{s.duration} min</td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ${cfg.bg}`}>
                        <Icon className="w-3 h-3" />{s.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-gray-500 dark:text-gray-400 max-w-xs truncate">{s.notes || '—'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
