/**
 * BodyStatsTab — Circumference measurements, BMI, WHR, weight/body fat charts.
 */

import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { TrendingDown, TrendingUp, Minus } from 'lucide-react';
import { type FullClientProfile, bmiCategory } from '@/lib/client-data';

const CIRCUMFERENCES = [
  { id: 'neck', label: 'Neck' },
  { id: 'shoulder', label: 'Shoulder' },
  { id: 'chest', label: 'Chest' },
  { id: 'waist', label: 'Waist' },
  { id: 'hips', label: 'Hips' },
  { id: 'thigh', label: 'Thigh' },
  { id: 'calf', label: 'Calf' },
  { id: 'arm', label: 'Arm' },
] as const;

type CircId = (typeof CIRCUMFERENCES)[number]['id'];

export default function BodyStatsTab({ client }: { client: FullClientProfile }) {
  const history = client.bodyStatsHistory;
  const current = history[0];
  const previous = history[1];

  const weightData = [...history].reverse().map((h) => ({ date: h.date.slice(5), weight: h.weight, bodyFat: h.bodyFatPercent }));

  const getDelta = (id: CircId) => {
    if (!previous) return null;
    return Math.round(((current as unknown as Record<string, number>)[id] - (previous as unknown as Record<string, number>)[id]) * 10) / 10;
  };

  return (
    <div className="space-y-6">
      {/* Weight & Body Fat Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Weight Trend (90 days)</h3>
          <div className="h-52">
            <ResponsiveContainer>
              <AreaChart data={weightData}>
                <defs><linearGradient id="wGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#00AEEF" stopOpacity={0.3} /><stop offset="95%" stopColor="#00AEEF" stopOpacity={0} /></linearGradient></defs>
                <XAxis dataKey="date" tick={{ fontSize: 11 }} />
                <YAxis domain={['dataMin - 3', 'dataMax + 3']} tick={{ fontSize: 11 }} />
                <Tooltip contentStyle={{ borderRadius: '8px', border: 'none' }} />
                <Area type="monotone" dataKey="weight" stroke="#00AEEF" strokeWidth={2} fill="url(#wGrad)" dot={false} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
        <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Body Fat % Trend</h3>
          <div className="h-52">
            <ResponsiveContainer>
              <AreaChart data={weightData}>
                <defs><linearGradient id="bfGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#22C55E" stopOpacity={0.3} /><stop offset="95%" stopColor="#22C55E" stopOpacity={0} /></linearGradient></defs>
                <XAxis dataKey="date" tick={{ fontSize: 11 }} />
                <YAxis domain={['dataMin - 2', 'dataMax + 2']} tick={{ fontSize: 11 }} />
                <Tooltip contentStyle={{ borderRadius: '8px', border: 'none' }} />
                <Area type="monotone" dataKey="bodyFat" stroke="#22C55E" strokeWidth={2} fill="url(#bfGrad)" dot={false} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* BMI & WHR Summary */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-[#141414] rounded-xl p-4 border border-gray-100 dark:border-white/5 text-center">
          <p className="text-xs text-gray-500 dark:text-gray-400">BMI</p>
          <p className="text-2xl font-bold text-gray-900 dark:text-white font-mono mt-1">{current.bmi}</p>
          <p className="text-xs text-gray-500 mt-1">{bmiCategory(current.bmi)}</p>
        </div>
        <div className="bg-white dark:bg-[#141414] rounded-xl p-4 border border-gray-100 dark:border-white/5 text-center">
          <p className="text-xs text-gray-500 dark:text-gray-400">Waist-to-Hip</p>
          <p className="text-2xl font-bold text-gray-900 dark:text-white font-mono mt-1">{current.whr}</p>
          <p className="text-xs text-gray-500 mt-1">{current.whr < 0.9 ? 'Healthy' : 'At Risk'}</p>
        </div>
        <div className="bg-white dark:bg-[#141414] rounded-xl p-4 border border-gray-100 dark:border-white/5 text-center">
          <p className="text-xs text-gray-500 dark:text-gray-400">Body Fat %</p>
          <p className="text-2xl font-bold text-[#00AEEF] font-mono mt-1">{current.bodyFatPercent}%</p>
          <p className="text-xs text-gray-500 mt-1">{current.bodyFatPercent < 15 ? 'Athletic' : current.bodyFatPercent < 20 ? 'Fitness' : 'Average'}</p>
        </div>
        <div className="bg-white dark:bg-[#141414] rounded-xl p-4 border border-gray-100 dark:border-white/5 text-center">
          <p className="text-xs text-gray-500 dark:text-gray-400">Weight</p>
          <p className="text-2xl font-bold text-gray-900 dark:text-white font-mono mt-1">{current.weight} kg</p>
          {previous && (
            <p className={`text-xs mt-1 ${current.weight < previous.weight ? 'text-emerald-600' : 'text-red-500'}`}>
              {current.weight < previous.weight ? '↓' : '↑'} {Math.abs(Math.round((current.weight - previous.weight) * 10) / 10)} kg
            </p>
          )}
        </div>
      </div>

      {/* Circumference Grid */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Circumference Measurements (cm)</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {CIRCUMFERENCES.map((c) => {
            const val = (current as unknown as Record<string, number>)[c.id];
            const delta = getDelta(c.id);
            return (
              <div key={c.id} className="bg-gray-50 dark:bg-[#1A1A1A] rounded-xl p-4">
                <p className="text-xs text-gray-500 dark:text-gray-400">{c.label}</p>
                <p className="text-xl font-bold text-gray-900 dark:text-white font-mono mt-1">{val} cm</p>
                {delta !== null && (
                  <span className={`inline-flex items-center gap-0.5 text-xs mt-1 ${delta < 0 ? 'text-emerald-600' : delta > 0 ? 'text-amber-600' : 'text-gray-400'}`}>
                    {delta < 0 ? <TrendingDown className="w-3 h-3" /> : delta > 0 ? <TrendingUp className="w-3 h-3" /> : <Minus className="w-3 h-3" />}
                    {delta > 0 ? '+' : ''}{delta} cm
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Progress Photos Placeholder */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Progress Photos</h3>
        <div className="grid grid-cols-3 gap-4">
          {['Front View', 'Side View', 'Back View'].map((view) => (
            <div key={view} className="aspect-[3/4] rounded-xl border-2 border-dashed border-gray-200 dark:border-white/10 flex flex-col items-center justify-center text-gray-400 dark:text-gray-500">
              <p className="text-sm font-medium">{view}</p>
              <p className="text-xs mt-1">Upload photo</p>
            </div>
          ))}
        </div>
      </div>

      {/* Comparison Table */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl border border-gray-100 dark:border-white/5 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead><tr className="bg-gray-50 dark:bg-[#1A1A1A] text-gray-500 dark:text-gray-400 text-xs uppercase">
              <th className="text-left px-4 py-3">Measurement</th>
              <th className="text-right px-4 py-3">Current</th>
              <th className="text-right px-4 py-3">Previous</th>
              <th className="text-right px-4 py-3">Change</th>
            </tr></thead>
            <tbody className="divide-y divide-gray-100 dark:divide-white/5">
              {CIRCUMFERENCES.map((c) => {
                const val = (current as unknown as Record<string, number>)[c.id];
                const prev = previous ? (previous as unknown as Record<string, number>)[c.id] : null;
                const change = prev ? Math.round((val - prev) * 10) / 10 : null;
                return (
                  <tr key={c.id} className="hover:bg-gray-50 dark:hover:bg-[#1A1A1A]">
                    <td className="px-4 py-3 text-gray-700 dark:text-gray-300">{c.label}</td>
                    <td className="text-right px-4 py-3 font-mono text-gray-900 dark:text-white">{val} cm</td>
                    <td className="text-right px-4 py-3 font-mono text-gray-500">{prev ?? '--'} cm</td>
                    <td className={`text-right px-4 py-3 font-mono ${change !== null ? (change < 0 ? 'text-emerald-600' : change > 0 ? 'text-amber-600' : 'text-gray-400') : 'text-gray-400'}`}>
                      {change !== null ? `${change > 0 ? '+' : ''}${change} cm` : '--'}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
