/**
 * CalendarTab — Mini week view of client sessions.
 */

import { useState } from 'react';
import { format, startOfWeek, addDays } from 'date-fns';
import { Clock } from 'lucide-react';
import { type FullClientProfile } from '@/lib/client-data';

const STATUS_COLORS: Record<string, string> = {
  completed: 'bg-emerald-100 border-emerald-300 text-emerald-800 dark:bg-emerald-900/20 dark:border-emerald-700 dark:text-emerald-300',
  confirmed: 'bg-blue-100 border-blue-300 text-blue-800 dark:bg-blue-900/20 dark:border-blue-700 dark:text-blue-300',
  pending: 'bg-yellow-100 border-yellow-300 text-yellow-800 dark:bg-yellow-900/20 dark:border-yellow-700 dark:text-yellow-300',
  cancelled: 'bg-red-100 border-red-300 text-red-800 dark:bg-red-900/20 dark:border-red-700 dark:text-red-300',
};

export default function CalendarTab({ client }: { client: FullClientProfile }) {
  const [weekOffset, setWeekOffset] = useState(0);
  const weekStart = startOfWeek(addDays(new Date(), weekOffset * 7), { weekStartsOn: 1 });
  const days = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));

  const getSessionsForDay = (dateStr: string) =>
    client.sessions.filter((s) => s.date === dateStr);

  return (
    <div className="space-y-4">
      {/* Week Navigation */}
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400">
          Week of {format(weekStart, 'MMM d, yyyy')}
        </h3>
        <div className="flex gap-2">
          <button onClick={() => setWeekOffset(weekOffset - 1)} className="px-3 py-1.5 rounded-lg bg-gray-100 dark:bg-[#1A1A1A] text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/5">← Prev</button>
          <button onClick={() => setWeekOffset(0)} className="px-3 py-1.5 rounded-lg bg-gray-100 dark:bg-[#1A1A1A] text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/5">Today</button>
          <button onClick={() => setWeekOffset(weekOffset + 1)} className="px-3 py-1.5 rounded-lg bg-gray-100 dark:bg-[#1A1A1A] text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/5">Next →</button>
        </div>
      </div>

      {/* Mini Week Grid */}
      <div className="grid grid-cols-7 gap-2">
        {days.map((day) => {
          const isToday = format(day, 'yyyy-MM-dd') === format(new Date(), 'yyyy-MM-dd');
          const daySessions = getSessionsForDay(format(day, 'yyyy-MM-dd'));
          return (
            <div
              key={day.toISOString()}
              className={`rounded-xl border p-3 min-h-[120px] ${
                isToday
                  ? 'border-[#00AEEF] bg-[#00AEEF]/5'
                  : 'border-gray-100 dark:border-white/5 bg-white dark:bg-[#141414]'
              }`}
            >
              <p className={`text-xs font-medium ${isToday ? 'text-[#00AEEF]' : 'text-gray-500 dark:text-gray-400'}`}>
                {format(day, 'EEE')}
              </p>
              <p className="text-lg font-bold text-gray-900 dark:text-white font-mono">{format(day, 'd')}</p>
              <div className="mt-2 space-y-1">
                {daySessions.slice(0, 3).map((s) => (
                  <div key={s.id} className={`text-[10px] px-1.5 py-0.5 rounded border ${STATUS_COLORS[s.status] || STATUS_COLORS.pending} truncate`}>
                    {s.type}
                  </div>
                ))}
                {daySessions.length > 3 && (
                  <p className="text-[10px] text-gray-400">+{daySessions.length - 3} more</p>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Upcoming Sessions List */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Upcoming Sessions</h3>
        {client.sessions.filter((s) => s.status === 'confirmed' || s.status === 'pending').length === 0 ? (
          <p className="text-sm text-gray-400">No upcoming sessions.</p>
        ) : (
          <div className="space-y-3">
            {client.sessions
              .filter((s) => s.status === 'confirmed' || s.status === 'pending')
              .slice(0, 5)
              .map((s) => (
                <div key={s.id} className="flex items-center gap-3 py-2 border-b border-gray-50 dark:border-white/5 last:border-0">
                  <div className="w-10 h-10 rounded-lg bg-gray-100 dark:bg-[#1A1A1A] flex items-center justify-center">
                    <Clock className="w-5 h-5 text-[#00AEEF]" />
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-medium text-gray-900 dark:text-white">{s.type}</p>
                    <p className="text-xs text-gray-500">{format(new Date(s.date), 'EEE, MMM d')} · {s.duration} min</p>
                  </div>
                  <span className={`text-xs px-2 py-0.5 rounded-full ${STATUS_COLORS[s.status]}`}>{s.status}</span>
                </div>
              ))}
          </div>
        )}
      </div>
    </div>
  );
}
