/**
 * LifestyleTab — 7-category radar chart with detailed score breakdown.
 */

import { useState } from 'react';
import { RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Tooltip, ResponsiveContainer } from 'recharts';
import { format } from 'date-fns';
import { type FullClientProfile } from '@/lib/client-data';

const CATEGORIES = [
  { key: 'sleep', label: 'Sleep', color: '#00AEEF' },
  { key: 'stress', label: 'Stress', color: '#EC4899' },
  { key: 'nutrition', label: 'Nutrition', color: '#22C55E' },
  { key: 'hydration', label: 'Hydration', color: '#3B82F6' },
  { key: 'energy', label: 'Energy', color: '#EAB308' },
  { key: 'digestion', label: 'Digestion', color: '#F97316' },
  { key: 'recovery', label: 'Recovery', color: '#A855F7' },
];

export default function LifestyleTab({ client }: { client: FullClientProfile }) {
  const [selectedEntry, setSelectedEntry] = useState(0);
  const history = client.lifestyleHistory;
  const entry = history[selectedEntry] || history[0];

  const radarData = CATEGORIES.map((c) => ({
    category: c.label,
    score: entry.scores[c.key as keyof typeof entry.scores] as number,
    fullMark: 10,
  }));

  const avgScore = Math.round(CATEGORIES.reduce((sum, c) => sum + (entry.scores[c.key as keyof typeof entry.scores] as number), 0) / CATEGORIES.length * 10) / 10;

  return (
    <div className="space-y-6">
      {/* Score Header */}
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-gray-500 dark:text-gray-400">Overall Lifestyle Score</p>
          <p className="text-3xl font-bold text-gray-900 dark:text-white font-mono mt-1">{avgScore}<span className="text-lg text-gray-400">/10</span></p>
        </div>
        <select
          value={selectedEntry}
          onChange={(e) => setSelectedEntry(Number(e.target.value))}
          className="text-sm border border-gray-200 dark:border-white/10 rounded-lg px-3 py-1.5 bg-white dark:bg-[#1A1A1A] text-gray-700 dark:text-gray-300"
        >
          {history.map((h, i) => (
            <option key={h.date} value={i}>{format(new Date(h.date), 'MMM d, yyyy')}</option>
          ))}
        </select>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Radar Chart */}
        <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
          <div className="h-80">
            <ResponsiveContainer>
              <RadarChart data={radarData}>
                <PolarGrid stroke="#E5E7EB" />
                <PolarAngleAxis dataKey="category" tick={{ fontSize: 12, fill: '#6B7280' }} />
                <PolarRadiusAxis angle={90} domain={[0, 10]} tick={{ fontSize: 10 }} />
                <Radar name="Score" dataKey="score" stroke="#00AEEF" fill="#00AEEF" fillOpacity={0.2} strokeWidth={2} />
                <Tooltip contentStyle={{ borderRadius: '8px', border: 'none' }} />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Score Breakdown */}
        <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5 space-y-4">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400">Category Breakdown</h3>
          {CATEGORIES.map((c) => {
            const score = entry.scores[c.key as keyof typeof entry.scores] as number;
            return (
              <div key={c.key}>
                <div className="flex justify-between text-sm mb-1.5">
                  <span className="text-gray-700 dark:text-gray-300">{c.label}</span>
                  <span className="font-medium font-mono text-gray-900 dark:text-white">{score}/10</span>
                </div>
                <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                  <div className="h-full rounded-full transition-all duration-700" style={{ width: `${score * 10}%`, backgroundColor: c.color }} />
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* History Table */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl border border-gray-100 dark:border-white/5 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead><tr className="bg-gray-50 dark:bg-[#1A1A1A] text-gray-500 dark:text-gray-400 text-xs uppercase">
              <th className="text-left px-4 py-3">Date</th>
              <th className="text-left px-4 py-3">Assessor</th>
              {CATEGORIES.map((c) => <th key={c.key} className="text-center px-3 py-3">{c.label}</th>)}
              <th className="text-center px-4 py-3">Avg</th>
            </tr></thead>
            <tbody className="divide-y divide-gray-100 dark:divide-white/5">
              {history.map((h) => {
                const avg = Math.round(CATEGORIES.reduce((s, c) => s + (h.scores[c.key as keyof typeof h.scores] as number), 0) / CATEGORIES.length * 10) / 10;
                return (
                  <tr key={h.date} className="hover:bg-gray-50 dark:hover:bg-[#1A1A1A]">
                    <td className="px-4 py-3 text-gray-700 dark:text-gray-300">{format(new Date(h.date), 'MMM d')}</td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">{h.assessor}</td>
                    {CATEGORIES.map((c) => (
                      <td key={c.key} className="text-center px-3 py-3 font-mono text-gray-600 dark:text-gray-400">
                        {h.scores[c.key as keyof typeof h.scores]}
                      </td>
                    ))}
                    <td className="text-center px-4 py-3 font-mono font-medium text-[#00AEEF]">{avg}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
