/**
 * NotesTab — Chronological client notes timeline with add-note functionality.
 */

import { useState } from 'react';
import { motion } from 'framer-motion';
import { format } from 'date-fns';
import { Plus, Search, StickyNote, ClipboardCheck, MessageSquare } from 'lucide-react';
import { type FullClientProfile, type ClientNote } from '@/lib/client-data';

const CATEGORIES: ClientNote['category'][] = ['Trainer Note', 'Assessment Note', 'General'];

export default function NotesTab({ client }: { client: FullClientProfile }) {
  const [notes, setNotes] = useState<ClientNote[]>(client.notes);
  const [newNote, setNewNote] = useState('');
  const [newCategory, setNewCategory] = useState<ClientNote['category']>('Trainer Note');
  const [showForm, setShowForm] = useState(false);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState<ClientNote['category'] | 'All'>('All');

  const categoryIcons = {
    'Trainer Note': StickyNote,
    'Assessment Note': ClipboardCheck,
    'General': MessageSquare,
  };
  const categoryColors = {
    'Trainer Note': 'bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400',
    'Assessment Note': 'bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400',
    'General': 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-400',
  };

  const filtered = notes.filter((n) => {
    const matchesSearch = !search || n.content.toLowerCase().includes(search.toLowerCase());
    const matchesFilter = filter === 'All' || n.category === filter;
    return matchesSearch && matchesFilter;
  });

  const addNote = () => {
    if (!newNote.trim()) return;
    const note: ClientNote = {
      id: `note-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      author: 'Azwar',
      category: newCategory,
      content: newNote.trim(),
    };
    setNotes([note, ...notes]);
    setNewNote('');
    setShowForm(false);
  };

  return (
    <div className="space-y-6">
      {/* Toolbar */}
      <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text" placeholder="Search notes..."
            value={search} onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2 rounded-xl border border-gray-200 dark:border-white/10 bg-white dark:bg-[#1A1A1A] text-sm text-gray-700 dark:text-gray-300 focus:border-[#00AEEF] focus:ring-2 focus:ring-[#00AEEF]/20 outline-none"
          />
        </div>
        <div className="flex gap-2">
          {(['All', ...CATEGORIES] as const).map((c) => (
            <button
              key={c}
              onClick={() => setFilter(c)}
              className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                filter === c ? 'bg-[#00AEEF] text-white' : 'bg-gray-100 dark:bg-[#1A1A1A] text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-white/5'
              }`}
            >{c}</button>
          ))}
          <button
            onClick={() => setShowForm(!showForm)}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[#00AEEF] text-white text-xs font-medium hover:bg-[#008DC4] transition-colors"
          >
            <Plus className="w-3.5 h-3.5" /> Add Note
          </button>
        </div>
      </div>

      {/* Add Note Form */}
      {showForm && (
        <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
          <select value={newCategory} onChange={(e) => setNewCategory(e.target.value as ClientNote['category'])} className="mb-3 text-sm border border-gray-200 dark:border-white/10 rounded-lg px-3 py-2 bg-white dark:bg-[#1A1A1A]">
            {CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
          <textarea
            value={newNote} onChange={(e) => setNewNote(e.target.value)}
            placeholder="Write your note here..."
            rows={3} className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50 dark:bg-[#1A1A1A] text-sm resize-none focus:border-[#00AEEF] outline-none"
          />
          <div className="flex justify-end gap-2 mt-3">
            <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm text-gray-500 hover:text-gray-700">Cancel</button>
            <button onClick={addNote} className="px-4 py-2 rounded-lg bg-[#00AEEF] text-white text-sm font-medium hover:bg-[#008DC4]">Save Note</button>
          </div>
        </motion.div>
      )}

      {/* Timeline */}
      {filtered.length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <StickyNote className="w-12 h-12 mx-auto mb-3 opacity-30" />
          <p className="text-sm">No notes found.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {filtered.map((note, i) => {
            const Icon = categoryIcons[note.category];
            return (
              <motion.div
                key={note.id}
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.03 }}
                className="bg-white dark:bg-[#141414] rounded-xl p-5 border border-gray-100 dark:border-white/5"
              >
                <div className="flex items-start justify-between mb-2">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${categoryColors[note.category]}`}>
                      <Icon className="w-4 h-4" />
                    </div>
                    <div>
                      <p className="text-sm font-medium text-gray-900 dark:text-white">{note.category}</p>
                      <p className="text-xs text-gray-500">{note.author} · {format(new Date(note.date), 'MMM d, yyyy')}</p>
                    </div>
                  </div>
                </div>
                <p className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed ml-11">{note.content}</p>
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}
