/**
 * DashboardTab — Client profile overview with progress ring, weight trend, and activity feed.
 */

import { motion } from 'framer-motion';
import { format } from 'date-fns';
import { PieChart, Pie, Cell, AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { Calendar, TrendingUp, Award, Dumbbell } from 'lucide-react';
import { type FullClientProfile, generateSparkline } from '@/lib/client-data';

const COLORS = { cyan: '#00AEEF', success: '#22C55E', bg: '#E5E7EB' };

const container = { hidden: {}, show: { transition: { staggerChildren: 0.06 } } };
const item = { hidden: { opacity: 0, y: 16 }, show: { opacity: 1, y: 0 } };

export default function DashboardTab({ client }: { client: FullClientProfile }) {
  const progress = client.complianceScore;
  const progressData = [{ name: 'done', value: progress }, { name: 'remaining', value: 100 - progress }];
  const weightData = generateSparkline(30, client.weight, 2).map((v, i) => ({ day: i + 1, weight: v }));
  const recentActivity = client.sessions.slice(0, 5);
  const goals = [
    { label: 'Weight Target', current: client.weight, target: client.weight - 5, unit: 'kg', percent: 72 },
    { label: 'Body Fat Goal', current: client.bodyFatPercent, target: 15, unit: '%', percent: Math.round((1 - client.bodyFatPercent / 25) * 100) },
    { label: 'Sessions / Month', current: 12, target: 16, unit: '', percent: 75 },
  ];

  return (
    <motion.div variants={container} initial="hidden" animate="show" className="space-y-6">
      {/* Top Row: Progress Ring + Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Program Progress Ring */}
        <motion.div variants={item} className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-sm">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Program Progress</h3>
          <div className="w-40 h-40 mx-auto">
            <ResponsiveContainer>
              <PieChart>
                <Pie data={progressData} cx="50%" cy="50%" innerRadius={55} outerRadius={70} startAngle={90} endAngle={-270} dataKey="value" strokeWidth={0}>
                  <Cell fill={COLORS.cyan} />
                  <Cell fill={COLORS.bg} />
                </Pie>
              </PieChart>
            </ResponsiveContainer>
          </div>
          <p className="text-center text-3xl font-bold text-gray-900 dark:text-white font-mono -mt-24 mb-10">{progress}%</p>
        </motion.div>

        {/* Next Session + Quick Info */}
        <motion.div variants={item} className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-sm">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Next Session</h3>
          {recentActivity[0] ? (
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-[#00AEEF]/10 flex items-center justify-center">
                  <Calendar className="w-5 h-5 text-[#00AEEF]" />
                </div>
                <div>
                  <p className="font-medium text-gray-900 dark:text-white">{recentActivity[0].type}</p>
                  <p className="text-sm text-gray-500 dark:text-gray-400">{format(new Date(recentActivity[0].date), 'EEE, MMM d')}</p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3 mt-3">
                <div className="bg-gray-50 dark:bg-[#1A1A1A] rounded-lg p-3 text-center">
                  <Dumbbell className="w-4 h-4 text-[#00AEEF] mx-auto mb-1" />
                  <p className="text-xs text-gray-500">Program</p>
                  <p className="text-sm font-semibold text-gray-900 dark:text-white">{client.program}</p>
                </div>
                <div className="bg-gray-50 dark:bg-[#1A1A1A] rounded-lg p-3 text-center">
                  <Award className="w-4 h-4 text-emerald-500 mx-auto mb-1" />
                  <p className="text-xs text-gray-500">Compliance</p>
                  <p className="text-sm font-semibold text-gray-900 dark:text-white">{client.complianceScore}%</p>
                </div>
              </div>
            </div>
          ) : (
            <p className="text-gray-400 text-sm">No upcoming sessions</p>
          )}
        </motion.div>

        {/* Weight Trend Sparkline */}
        <motion.div variants={item} className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-sm">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-2">Weight Trend (30 days)</h3>
          <p className="text-2xl font-bold text-gray-900 dark:text-white font-mono mb-4">{client.weight} kg</p>
          <div className="h-28">
            <ResponsiveContainer>
              <AreaChart data={weightData}>
                <defs><linearGradient id="weightGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={COLORS.cyan} stopOpacity={0.3} /><stop offset="95%" stopColor={COLORS.cyan} stopOpacity={0} /></linearGradient></defs>
                <XAxis dataKey="day" hide />
                <YAxis hide domain={['dataMin - 2', 'dataMax + 2']} />
                <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} />
                <Area type="monotone" dataKey="weight" stroke={COLORS.cyan} strokeWidth={2} fill="url(#weightGrad)" dot={false} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </motion.div>
      </div>

      {/* Goal Progress Bars */}
      <motion.div variants={item} className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-sm">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Goal Progress</h3>
        <div className="space-y-4">
          {goals.map((g) => (
            <div key={g.label}>
              <div className="flex justify-between text-sm mb-1.5">
                <span className="text-gray-700 dark:text-gray-300">{g.label}</span>
                <span className="text-gray-500 dark:text-gray-400">{g.current}{g.unit} → {g.target}{g.unit}</span>
              </div>
              <div className="h-2.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                <motion.div
                  initial={{ width: 0 }}
                  animate={{ width: `${Math.min(100, Math.max(0, g.percent))}%` }}
                  transition={{ duration: 0.8, ease: 'easeOut' }}
                  className="h-full rounded-full bg-gradient-to-r from-[#00AEEF] to-[#33BFF2]"
                />
              </div>
            </div>
          ))}
        </div>
      </motion.div>

      {/* Recent Activity */}
      <motion.div variants={item} className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-sm">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-4">Recent Activity</h3>
        <div className="space-y-3">
          {recentActivity.map((s) => (
            <div key={s.id} className="flex items-center gap-3 py-2 border-b border-gray-50 dark:border-white/5 last:border-0">
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
                s.status === 'completed' ? 'bg-emerald-50 text-emerald-600' :
                s.status === 'confirmed' ? 'bg-blue-50 text-blue-600' :
                s.status === 'pending' ? 'bg-yellow-50 text-yellow-600' :
                'bg-red-50 text-red-600'
              }`}>
                {s.status === 'completed' ? <Award className="w-4 h-4" /> :
                 s.status === 'cancelled' ? <TrendingUp className="w-4 h-4" /> :
                 <Dumbbell className="w-4 h-4" />}
              </div>
              <div className="flex-1">
                <p className="text-sm font-medium text-gray-900 dark:text-white">{s.type}</p>
                <p className="text-xs text-gray-500">{format(new Date(s.date), 'MMM d, yyyy')} · {s.duration} min</p>
              </div>
              <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                s.status === 'completed' ? 'bg-emerald-50 text-emerald-700' :
                s.status === 'confirmed' ? 'bg-blue-50 text-blue-700' :
                s.status === 'pending' ? 'bg-yellow-50 text-yellow-700' :
                'bg-red-50 text-red-700'
              }`}>{s.status}</span>
            </div>
          ))}
        </div>
      </motion.div>
    </motion.div>
  );
}
