/**
 * BioPrintTab — 8-site skinfold measurement tracking with history and body fat calculation.
 */

import { useState } from 'react';
import { format } from 'date-fns';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { TrendingDown, TrendingUp, Minus } from 'lucide-react';
import { type FullClientProfile } from '@/lib/client-data';

const SITES = [
  { id: 'subscapular', label: 'Subscapular' },
  { id: 'tricep', label: 'Tricep' },
  { id: 'bicep', label: 'Bicep' },
  { id: 'iliac', label: 'Iliac Crest' },
  { id: 'supraspinal', label: 'Supraspinal' },
  { id: 'abdominal', label: 'Abdominal' },
  { id: 'thigh', label: 'Thigh' },
  { id: 'calf', label: 'Calf' },
] as const;

type SiteId = (typeof SITES)[number]['id'];

export default function BioPrintTab({ client }: { client: FullClientProfile }) {
  const [selectedEntry, setSelectedEntry] = useState(0);
  const history = client.bioPrintHistory;
  const current = history[selectedEntry] || history[0];
  const previous = history[selectedEntry + 1];

  const getDelta = (site: SiteId) => {
    if (!previous) return null;
    const val = (current as unknown as Record<string, number>)[site];
    const prev = (previous as unknown as Record<string, number>)[site];
    return Math.round((val - prev) * 10) / 10;
  };

  const deltaBodyFat = previous ? Math.round((current.bodyFatPercent - previous.bodyFatPercent) * 10) / 10 : null;

  const trendData = [...history].reverse().map((h) => ({
    date: format(new Date(h.date), 'MMM d'),
    bodyFat: h.bodyFatPercent,
    sum: h.sum,
  }));

  return (
    <div className="space-y-6">
      {/* Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Sum of 8', value: `${current.sum} mm`, color: 'text-gray-900 dark:text-white' },
          { label: 'Body Fat %', value: `${current.bodyFatPercent}%`, color: 'text-[#00AEEF]' },
          { label: 'Lean Mass', value: `${current.leanMass} kg`, color: 'text-emerald-600 dark:text-emerald-400' },
          { label: 'Fat Mass', value: `${current.fatMass} kg`, color: 'text-amber-600 dark:text-amber-400' },
        ].map((card) => (
          <div key={card.label} className="bg-white dark:bg-[#141414] rounded-xl p-4 border border-gray-100 dark:border-white/5">
            <p className="text-xs text-gray-500 dark:text-gray-400 uppercase">{card.label}</p>
            <p className={`text-xl font-bold font-mono mt-1 ${card.color}`}>{card.value}</p>
          </div>
        ))}
      </div>

      {/* Body Fat Trend */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400">Body Fat % Trend</h3>
          {deltaBodyFat !== null && (
            <span className={`flex items-center gap-1 text-sm font-medium ${deltaBodyFat < 0 ? 'text-emerald-600' : 'text-red-500'}`}>
              {deltaBodyFat < 0 ? <TrendingDown className="w-4 h-4" /> : <TrendingUp className="w-4 h-4" />}
              {deltaBodyFat > 0 ? '+' : ''}{deltaBodyFat}% from previous
            </span>
          )}
        </div>
        <div className="h-48">
          <ResponsiveContainer>
            <LineChart data={trendData}>
              <XAxis dataKey="date" tick={{ fontSize: 12 }} />
              <YAxis domain={['dataMin - 2', 'dataMax + 2']} tick={{ fontSize: 12 }} />
              <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} />
              <Line type="monotone" dataKey="bodyFat" stroke="#00AEEF" strokeWidth={2} dot={{ fill: '#00AEEF', r: 4 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Measurements Grid */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl p-6 border border-gray-100 dark:border-white/5">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400">8-Site Measurements</h3>
          <select
            value={selectedEntry}
            onChange={(e) => setSelectedEntry(Number(e.target.value))}
            className="text-sm border border-gray-200 dark:border-white/10 rounded-lg px-3 py-1.5 bg-white dark:bg-[#1A1A1A] text-gray-700 dark:text-gray-300"
          >
            {history.map((h, i) => (
              <option key={h.date} value={i}>{format(new Date(h.date), 'MMM d, yyyy')}</option>
            ))}
          </select>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {SITES.map((site) => {
            const value = (current as unknown as Record<string, number>)[site.id];
            const delta = getDelta(site.id);
            return (
              <div key={site.id} className="bg-gray-50 dark:bg-[#1A1A1A] rounded-xl p-4">
                <p className="text-xs text-gray-500 dark:text-gray-400">{site.label}</p>
                <p className="text-xl font-bold text-gray-900 dark:text-white font-mono mt-1">{value} mm</p>
                {delta !== null && (
                  <span className={`inline-flex items-center gap-0.5 text-xs mt-1 ${delta < 0 ? 'text-emerald-600' : 'text-red-500'}`}>
                    {delta < 0 ? <TrendingDown className="w-3 h-3" /> : delta > 0 ? <TrendingUp className="w-3 h-3" /> : <Minus className="w-3 h-3" />}
                    {delta > 0 ? '+' : ''}{delta} mm
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* History Table */}
      <div className="bg-white dark:bg-[#141414] rounded-2xl border border-gray-100 dark:border-white/5 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gray-50 dark:bg-[#1A1A1A] text-gray-500 dark:text-gray-400 text-xs uppercase">
                <th className="text-left px-4 py-3 font-medium">Date</th>
                {SITES.map((s) => <th key={s.id} className="text-right px-3 py-3 font-medium">{s.label}</th>)}
                <th className="text-right px-4 py-3 font-medium">BF%</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-white/5">
              {history.map((h) => (
                <tr key={h.date} className="hover:bg-gray-50 dark:hover:bg-[#1A1A1A] transition-colors">
                  <td className="px-4 py-3 text-gray-700 dark:text-gray-300">{format(new Date(h.date), 'MMM d')}</td>
                  {SITES.map((s) => <td key={s.id} className="text-right px-3 py-3 font-mono text-gray-600 dark:text-gray-400">{(h as unknown as Record<string, number>)[s.id]}</td>)}
                  <td className="text-right px-4 py-3 font-mono font-medium text-[#00AEEF]">{h.bodyFatPercent}%</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
