/**
 * AzFIT Client Portal — Client Profile Data Types & Helpers
 * Provides strongly-typed client profile structures and data transformation utilities.
 */

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

/** Single BioPrint (skinfold) measurement entry. */
export interface BioPrintEntry {
  id: string;
  date: string; // ISO date
  site: string;
  value: number; // mm
  weight?: number;
  bodyFat?: number;
  bodyFatPercent?: number;
  sum?: number;
  sites?: string[];
}

/** A body measurement snapshot taken on a specific date. */
export interface BodyMeasurement {
  id: string;
  date: string; // ISO date
  weight: number; // kg
  bodyFat?: number; // percentage
  bodyFatPercent?: number; // alias for bodyFat
  neck?: number; // cm
  shoulder?: number; // cm
  chest?: number; // cm
  waist?: number; // cm
  hips?: number; // cm
  arms?: number; // cm
  arm?: number; // cm
  thigh?: number; // cm
  thighs?: number; // cm
  shoulders?: number; // cm
  calves?: number; // cm
  calf?: number; // cm
  notes?: string;
}

/** Lifestyle and habits data for a client. */
export interface LifestyleData {
  date?: string;
  sleepHours: number;
  sleepQuality: 'poor' | 'fair' | 'good' | 'excellent';
  stressLevel: number; // 1–10
  waterIntake: number; // liters per day
  stepCount: number;
  activityLevel: 'sedentary' | 'light' | 'moderate' | 'active' | 'very-active';
  occupation: string;
  dietaryPreference: string;
  allergies: string[];
  medications: string[];
  injuries: string[];
  smoking: boolean;
  alcohol: 'none' | 'occasional' | 'regular';
  scores: Record<string, number>;
}

/** A trainer note about a client. */
export interface ClientNote {
  id: string;
  date: string; // ISO date
  content: string;
  author: string;
  category: 'general' | 'session' | 'assessment' | 'nutrition' | 'medical';
}

/** A single training session entry. */
export interface SessionEntry {
  id: string;
  date: string; // ISO date
  type: string;
  duration: number; // minutes
  exercises: string[];
  notes: string;
  rating: number; // 1–5
  status?: string;
}

/** A training program assigned to a client. */
export interface ProgramEntry {
  id: string;
  name: string;
  startDate: string; // ISO date
  endDate?: string; // ISO date
  status: 'active' | 'completed' | 'cancelled';
  phases: number;
  method?: string;
  progress?: number;
  programId?: string;
}

/** Nutrition data and plan snapshot. */
export interface NutritionData {
  plan: string | null;
  dailyCalories: number;
  protein: number; // grams
  carbs: number; // grams
  fats: number; // grams
  waterIntake: number; // liters
  adherence: number; // percentage 0–100
  name?: string;
  type?: string;
  meals?: Array<{
    name: string;
    foods: Array<{
      name: string;
      calories: number;
      protein: number;
      carbs: number;
      fats: number;
      portion?: string;
    }>;
  }>;
}

/** A record/attachment (assessment, document, etc.). */
export interface RecordEntry {
  id: string;
  type: string;
  date: string; // ISO date
  title: string;
  description: string;
  files: string[]; // file paths or URLs
}

/** Complete client profile — all data sections combined. */
export interface FullClientProfile {
  id: string;
  name: string;
  email: string;
  phone?: string;
  dateOfBirth?: string; // ISO date
  gender: 'male' | 'female' | 'other';
  height?: number; // cm
  weight?: number; // kg (latest)
  bodyFat?: number; // percentage (latest)
  bodyFatPercent?: number; // alias for bodyFat
  age?: number;
  goal: string;
  status: string;
  joinDate: string; // ISO date
  avatar?: string; // URL or path
  avatarUrl?: string; // alias for avatar
  bioPrints: BioPrintEntry[];
  bioPrintHistory?: BioPrintEntry[]; // alias for bioPrints
  measurements: BodyMeasurement[];
  bodyStatsHistory?: BodyMeasurement[]; // alias for measurements
  lifestyle: LifestyleData;
  lifestyleHistory?: LifestyleData[];
  notes: ClientNote[];
  sessions: SessionEntry[];
  programs: ProgramEntry[];
  program?: string | null; // current program name
  complianceScore?: number;
  nutrition: NutritionData;
  records: RecordEntry[];
  database: Record<string, any>; // raw data export
}

