function generateBioPrints(seed: number, count: number): BioPrintEntry[] {
  const rng = seededRandom(seed + 100);
  const sites = ['tricep', 'subscapular', 'suprailiac', 'thigh', 'abdominal', 'chest', 'midaxillary'];
  const entries: BioPrintEntry[] = [];
  for (let i = 0; i < count; i++) {
    const date = addDays(new Date().toISOString().split('T')[0], -randInt(7, 120, rng));
    const numSites = randInt(3, 7, rng);
    const sum = randInt(40, 180, rng);
    const bodyFatPercent = Math.max(5, Math.min(50, Math.round(0.29669 * sum - 0.00043 * sum * sum + 0.02963 * 30 + 1.4072)));
    for (const site of pickMultiple(sites, numSites, rng)) {
      entries.push({
        id: `bp-${seed}-${i}-${site}`,
        date,
        site,
        value: randInt(5, 30, rng),
        bodyFatPercent,
        sum,
      });
    }
  }
  return entries;
}

function generateMeasurements(seed: number, count: number): BodyMeasurement[] {
  const rng = seededRandom(seed + 200);
  const entries: BodyMeasurement[] = [];
  for (let i = 0; i < count; i++) {
    const weight = randInt(50, 95, rng);
    const bodyFat = randInt(10, 35, rng);
    entries.push({
      id: `meas-${seed}-${i}`,
      date: addDays(new Date().toISOString().split('T')[0], -randInt(7, 180, rng)),
      weight,
      bodyFat,
      bodyFatPercent: bodyFat,
      neck: randInt(32, 45, rng),
      shoulder: randInt(92, 125, rng),
      chest: randInt(78, 115, rng),
      waist: randInt(58, 98, rng),
      hips: randInt(78, 108, rng),
      arms: randInt(24, 42, rng),
      arm: randInt(24, 42, rng),
      thigh: randInt(44, 68, rng),
      thighs: randInt(44, 68, rng),
      shoulders: randInt(92, 125, rng),
      calves: randInt(28, 48, rng),
      calf: randInt(28, 48, rng),
      notes: rng() > 0.6 ? 'Measured before breakfast. Consistent hydration.' : undefined,
    });
  }
  return entries.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

