/**
 * Generate a complete client profile with realistic demo data.
 * Uses the numeric index extracted from `clientId` (e.g., "demo-client-0" → 0)
 * to produce consistent, deterministic data per client.
 *
 * @param clientId Client identifier string (e.g. "demo-client-0")
 * @param index Optional explicit index. If omitted, extracted from clientId.
 */
export function generateClientProfile(clientId: string, index?: number): FullClientProfile {
  const extractedIndex = (index ?? parseInt(clientId.replace(/\D/g, ''), 10)) || 0;
  const tmpl = HK_CLIENT_TEMPLATES[extractedIndex % HK_CLIENT_TEMPLATES.length];
  const rng = seededRandom(extractedIndex + 1);

  const birthYear = randInt(1985, 1998, rng);
  const birthMonth = randInt(1, 12, rng);
  const birthDay = randInt(1, 28, rng);
  const dateOfBirth = `${birthYear}-${String(birthMonth).padStart(2, '0')}-${String(birthDay).padStart(2, '0')}`;

  // Latest weight/bodyFat from most recent measurement
  const measCount = randInt(4, 10, rng);
  const measurements = generateMeasurements(extractedIndex, measCount);
  const latestMeasurement = measurements[0];

  const bioPrints = generateBioPrints(extractedIndex, randInt(3, 6, rng));
  const lifestyle = generateLifestyle(extractedIndex);
  const notes = generateNotes(extractedIndex, randInt(3, 8, rng));
  const sessions = generateSessions(extractedIndex, randInt(6, 20, rng));
  const programs = generatePrograms(extractedIndex, randInt(1, 4, rng));
  const nutrition = generateNutrition(extractedIndex);
  const records = generateRecords(extractedIndex, randInt(2, 6, rng));

  const weight = latestMeasurement?.weight ?? randInt(55, 90, rng);
  const bodyFat = latestMeasurement?.bodyFat ?? randInt(12, 30, rng);
  const age = dateOfBirth ? Math.floor((Date.now() - new Date(dateOfBirth).getTime()) / (365.25 * 24 * 60 * 60 * 1000)) : 30;
  const currentProgram = programs.find((p) => p.status === 'active');

  const profile: FullClientProfile = {
    id: clientId,
    name: tmpl.name,
    email: tmpl.email,
    phone: tmpl.phone,
    dateOfBirth,
    gender: tmpl.gender,
    height: tmpl.height,
    weight,
    bodyFat,
    bodyFatPercent: bodyFat,
    age,
    goal: tmpl.goal,
    status: tmpl.status,
    joinDate: tmpl.joinDate,
    avatar: `/avatars/${clientId}.png`,
    avatarUrl: `/avatars/${clientId}.png`,
    bioPrints,
    bioPrintHistory: bioPrints,
    measurements,
    bodyStatsHistory: measurements,
    lifestyle,
    lifestyleHistory: [lifestyle],
    notes,
    sessions,
    programs,
    program: currentProgram?.name ?? programs[0]?.name ?? null,
    complianceScore: randInt(60, 98, rng),
    nutrition,
    records,
    database: {}, // populated below
  };

  // Populate the raw database export with all fields
  profile.database = {
    ...profile,
    bmi: profile.weight && profile.height ? (profile.weight / ((profile.height / 100) ** 2)).toFixed(1) : null,
    bmiCategory: profile.weight && profile.height ? bmiCategory(profile.weight / ((profile.height / 100) ** 2)) : null,
    estimatedBodyFat: calcBodyFat(bioPrints),
    age: dateOfBirth ? Math.floor((Date.now() - new Date(dateOfBirth).getTime()) / (365.25 * 24 * 60 * 60 * 1000)) : null,
    totalSessions: sessions.length,
    programCount: programs.length,
    lastMeasurementDate: measurements[0]?.date ?? null,
    daysSinceJoin: Math.floor((Date.now() - new Date(tmpl.joinDate).getTime()) / (1000 * 60 * 60 * 24)),
    exportedAt: new Date().toISOString(),
  };

  return profile;
}

/**
 * Calculate body fat percentage from BioPrint (skinfold) measurements.
 * Uses a simplified Jackson-Pollock 4-site formula:
 *   Male:   %BF = (0.29288 × sum) − (0.0005 × sum²) + (0.15845 × age) − 5.76377
 *   Female: %BF = (0.29669 × sum) − (0.00043 × sum²) + (0.02963 × age) + 1.4072
 *
 * @param bioPrints Array of BioPrint skinfold entries
 * @returns Estimated body fat percentage, or null if insufficient data
 */
export function calcBodyFat(bioPrints: BioPrintEntry[]): number | null {
  if (!bioPrints || bioPrints.length === 0) return null;

  // Group by date and pick the most recent set
  const byDate: Record<string, BioPrintEntry[]> = {};
  for (const bp of bioPrints) {
    if (!byDate[bp.date]) byDate[bp.date] = [];
    byDate[bp.date].push(bp);
  }

  const dates = Object.keys(byDate).sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
  const latest = byDate[dates[0]];
  if (!latest || latest.length < 3) return null;

  const sum = latest.reduce((acc, bp) => acc + bp.value, 0);

  // Default age 30 for demo; simplified formula
  const age = 30;

  // Use gender-neutral simplified estimate for demo purposes
  const bodyFat = 0.29669 * sum - 0.00043 * sum * sum + 0.02963 * age + 1.4072;

  return Math.max(5, Math.min(50, Math.round(bodyFat * 10) / 10));
}

/**
 * Determine BMI category and associated color.
 * @param bmi Body Mass Index value
 * @returns Object with category name and color code
 */
export function bmiCategory(bmi: number): { category: string; color: string } {
  if (bmi < 18.5) return { category: 'Underweight', color: '#3b82f6' }; // blue-500
  if (bmi < 23) return { category: 'Normal', color: '#22c55e' }; // green-500
  if (bmi < 25) return { category: 'Overweight', color: '#eab308' }; // yellow-500
  if (bmi < 30) return { category: 'Obese I', color: '#f97316' }; // orange-500
  return { category: 'Obese II+', color: '#ef4444' }; // red-500
}

/**
 * Generate sparkline data — array of random numbers for mini charts.
 * @param count Number of data points (default: 20)
 */
export function generateSparkline(count: number = 20): number[] {
  const rng = seededRandom(999);
  return Array.from({ length: count }, () => randInt(60, 100, rng));
}

/**
 * Format a date string or Date object to HK display format (DD/MM/YYYY).
 * @param date ISO date string or Date object
 */
export function formatDateDisplay(date: string | Date): string {
  const d = typeof date === 'string' ? new Date(date) : date;
  if (isNaN(d.getTime())) return 'Invalid date';
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
}
